# VALKYRIE PHONE - MAP TILE BUILDER
#
# Builds the 3D map the phone's Maps app draws, from the game files already
# on your PC. Nothing is downloaded or uploaded.
#
# 1. Install Python 3 and tick "Add Python to PATH".
# 2. Open this folder in PowerShell.
# 3. Test:  .uild-phone-map.ps1 -GamePath "C:\Games\GTA San Andreas" -Test
# 4. Build: .uild-phone-map.ps1 -GamePath "C:\Games\GTA San Andreas"
#
# The game path is the folder with gta_sa.exe (or gta_pe.exe). The map is
# written there as the Valkyrie-radar-tiles folder, which the phone reads.
# A full build takes a while and needs several gigabytes of free space.
param(
    [string] $GamePath,
    [string] $WorkPath,
    [int] $Jobs = 4,
    [switch] $Test
)
$ErrorActionPreference = 'Stop'
if (-not $WorkPath) {
    $WorkPath = Join-Path (Split-Path -Parent $MyInvocation.MyCommand.Path) 'Valkyrie-phone-map-work'
}
$temp = Join-Path ([IO.Path]::GetTempPath()) ('ValkyrieRadar-' + [Guid]::NewGuid().ToString('N'))
New-Item -ItemType Directory -Path $temp | Out-Null
try {
    $zip = Join-Path $temp 'builder.zip'
