    Expand-Archive -LiteralPath $zip -DestinationPath $temp
    # The tiles only: the phone draws the map itself, so no radar ASI is
    # installed.
    $arguments = @{ WorkPath = $WorkPath; Jobs = $Jobs; SkipInstall = $true }
    if ($GamePath) { $arguments.GamePath = $GamePath }
